'use strict';

// The compatibility matrix (#28) must match the test fixtures and the
// physical test status: COMPATIBILITY.md is generated by tests/compat.js.
// Run: node tests/compat.test.js   (from the repository root)

const fs = require('fs');
const assert = require('assert/strict');
const { build, FILE } = require('./compat');
const { CHARGERS, BATTERIES, CARS } = require('./fixtures');

let failures = 0;
function check(name, fn) {
  try {
    fn();
    console.log('  ok  ', name);
  } catch (err) {
    failures++;
    console.log('  FAIL', name, '-', err.message);
  }
}

const text = build();
const saved = fs.existsSync(FILE) ? fs.readFileSync(FILE, 'utf8') : '';

check('COMPATIBILITY.md is up to date (run: node tests/compat.js write)', () => {
  assert.equal(saved, text, 'COMPATIBILITY.md differs from what tests/compat.js builds');
});

check('every charger, car and home battery of the fixtures is listed', () => {
  for (const c of CHARGERS) assert.ok(text.includes(`| ${c.brand}`), c.brand);
  for (const c of CARS) assert.ok(text.includes(`| ${c.brand} |`), c.brand);
  for (const b of BATTERIES) assert.ok(text.includes(`| \`${b.platform}\``), b.platform);
});

check('read-only devices are marked and never shown as steerable', () => {
  assert.match(text, /\| Tesla Wall Connector \*\*\(read only\)\*\* \| `tesla_wall_connector` \| yes \| – \| – \| – \|/);
  for (const b of BATTERIES.filter((x) => x.expect && x.expect.readOnly)) {
    assert.ok(text.includes(`| \`${b.platform}\` **(read only)** | yes | advice only |`), b.platform);
  }
});

check('physical test status only shows known states, and nothing personal', () => {
  const ph = JSON.parse(fs.readFileSync(require('path').join(__dirname, 'physical.json'), 'utf8'));
  for (const group of ['chargers', 'cars', 'batteries']) {
    for (const [k, v] of Object.entries(ph[group] || {})) {
      assert.ok(['verified', 'partly', 'problem'].includes(v.status), `${group}.${k}: ${v.status}`);
      assert.ok(!/\b[a-z_]+\.[a-z0-9_]+\b/.test(String(v.note || '')), `${group}.${k}: no entity ids in notes`);
    }
  }
});

console.log(failures ? `\n${failures} failed` : '\nAll compatibility checks passed');
process.exitCode = failures ? 1 : 0;
